fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Requires that the input vectors are of equal length
    // Ensures that the output vector has the same length as the input vectors
    // The result vector contains true if the corresponding element in `a` is less than in `b`
    // and false otherwise.
    // Decreases clause is not necessary here as there is no recursive call or loop that needs it.

    // Precondition: a and b must have the same length
    // This is an invariant that must hold true before the function proceeds
    assert!(a.len() == b.len(), "Input arrays must have the same length");

    // Create a new vector to hold the results
    let mut result = Vec::with_capacity(a.len());

    // Iterate over the elements of both arrays
    for (x, y) in a.iter().zip(b.iter()) {
        // Push the comparison result into the result vector
        result.push(x < y);
    }

    // Postcondition: The result vector must have the same length as the input vectors
    // and each element in the result vector is the result of the comparison of the corresponding elements in `a` and `b`.
    assert_eq!(result.len(), a.len(), "Result vector must have the same length as input vectors");

    result
}